@SpringBootApplication
class OrdersApplication

fun main(args: Array<String>) {
    runApplication<OrdersApplication>(*args)
}

@Configuration(proxyBeanMethods = false)
class TimeConfig {
    @Bean java.time.Clock clock() {
        return java.time.Clock.systemUTC();
    }
}

@ConfigurationProperties("orders")
@Validated
data class OrderProperties(
    @field:Min(1) val maxQuantity: Int
)

@Bean
ApplicationRunner showMode(OrderProperties properties) {
    return args -> System.out.println("maxQuantity=" + properties.maxQuantity());
}
